# Pre-generates a superflat creative playtest world in every "BI *" Prism
# instance and makes Prism launch straight into it (JoinWorldOnLaunch ->
# --quickPlaySingleplayer), with a datapack that hands the player a kit of
# pre-filled bundles on first join.
#
# The world is generated by that era's OWN dedicated server (`level-type=flat`,
# `gamemode=creative`, peaceful, no structures/mobs) because 1.21.9+ no longer
# stores world settings in level.dat (they moved to data/*/world_gen_settings.dat
# and dimensions/), while older eras still embed them. Letting the server write
# the format guarantees every era gets a valid save. The server also parses the
# kit datapack on a second start, so every give/component command is validated.
#
#   powershell -File ..\tools\make-playtest-worlds.ps1
#   powershell -File ..\tools\make-playtest-worlds.ps1 -Only 'BI Fabric 1.21.2-1.21.3'
#
# Prism must be closed when this changes instance.cfg.
param(
    [string]$Repo = '',
    [string]$PrismData = "$env:APPDATA\PrismLauncher",
    [string]$WorldName = 'BundlePlaytest',
    [string[]]$Only = @()
)
$ErrorActionPreference = 'Stop'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
if (-not $Repo) {
    if (Test-Path (Join-Path (Get-Location) 'gradlew.bat')) { $Repo = (Get-Location).Path }
    else { $Repo = Split-Path -Parent $PSScriptRoot }
}
$instanceRoot = Join-Path $PrismData 'instances'
$cfgPath = Join-Path $PrismData 'prismlauncher.cfg'
if (Test-Path $cfgPath) {
    $line = Get-Content $cfgPath | Where-Object { $_ -match '^InstanceDir=' } | Select-Object -First 1
    if ($line) { $instanceRoot = ($line -replace '^InstanceDir=', '') }
}
$work = Join-Path $env:TEMP 'bundleinventory-worldgen'
New-Item -ItemType Directory -Force (Join-Path $work 'servers') | Out-Null

# ------------------------------------------------------------ datapack -----
# Default config shows 6 rows x 8 slots, so a scroll test needs > 48 stacks.
# 60 single items stays under the 64-item bundle limit.
$scrollItems = @(
    'stone', 'granite', 'diorite', 'andesite', 'deepslate', 'cobbled_deepslate',
    'cobblestone', 'dirt', 'grass_block', 'sand', 'red_sand', 'gravel', 'clay',
    'clay_ball', 'flint', 'coal', 'charcoal', 'iron_ingot', 'gold_ingot',
    'copper_ingot', 'diamond', 'emerald', 'lapis_lazuli', 'quartz',
    'amethyst_shard', 'redstone', 'glowstone_dust', 'glowstone', 'netherrack',
    'soul_sand', 'obsidian', 'glass', 'sandstone', 'bricks', 'brick', 'oak_log',
    'birch_log', 'spruce_log', 'jungle_log', 'acacia_log', 'dark_oak_log',
    'oak_planks', 'birch_planks', 'spruce_planks', 'bookshelf', 'crafting_table',
    'furnace', 'chest', 'torch', 'lantern', 'apple', 'bread', 'carrot', 'potato',
    'beetroot', 'wheat', 'sugar', 'egg', 'feather', 'string'
)
$scroll = ($scrollItems | ForEach-Object { '{id:"minecraft:' + $_ + '",count:1}' }) -join ','

$kitLines = @(
    'tag @s add bundleinventory_playtest_kit',
    'give @s minecraft:bundle',
    'give @s minecraft:bundle[minecraft:bundle_contents=[{id:"minecraft:stone",count:32},{id:"minecraft:apple",count:8},{id:"minecraft:diamond",count:4}]]',
    'give @s minecraft:bundle[minecraft:bundle_contents=[{id:"minecraft:dirt",count:32},{id:"minecraft:stone",count:32}]]',
    'give @s minecraft:bundle[minecraft:bundle_contents=[{id:"minecraft:stone",count:63}]]',
    'give @s minecraft:bundle[minecraft:bundle_contents=[{id:"minecraft:bundle",count:1,components:{"minecraft:bundle_contents":[{id:"minecraft:diamond",count:8}]}},{id:"minecraft:ender_pearl",count:16},{id:"minecraft:apple",count:16}]]',
    ('give @s minecraft:bundle[minecraft:bundle_contents=[' + $scroll + ']]'),
    'give @s minecraft:bundle[minecraft:bundle_contents=[{id:"minecraft:diamond_sword",count:1},{id:"minecraft:diamond_pickaxe",count:1},{id:"minecraft:diamond_axe",count:1},{id:"minecraft:diamond_shovel",count:1},{id:"minecraft:bow",count:1},{id:"minecraft:shield",count:1},{id:"minecraft:elytra",count:1},{id:"minecraft:trident",count:1}]]',
    'give @s minecraft:bundle[minecraft:bundle_contents=[{id:"minecraft:apple",count:1}]]',
    'give @s minecraft:dirt 64',
    'give @s minecraft:cobblestone 64',
    'give @s minecraft:ender_pearl 16',
    'give @s minecraft:torch 64',
    'give @s minecraft:bread 16',
    'give @s minecraft:shulker_box 1',
    'give @s minecraft:bundle',
    'give @s minecraft:diamond_sword 1',
    'tellraw @s ["",{"text":"Bundle Inventory playtest kit","bold":true,"color":"gold"},{"text":"  hotbar: 1 empty, 2 partial 44/64, 3 full 64/64 (two stacks)","color":"gray"}]',
    'tellraw @s ["",{"text":"4 nearly full 63/64, 5 bundle-in-bundle, 6 scroll test (60 stacks), 7 unstackables, 8 one item, 9 dirt","color":"gray"}]',
    'tellraw @s ["",{"text":"Inventory: cobblestone, pearls, torches, bread, spare bundle, shulker box (bundles refuse it), sword","color":"gray"}]',
    'tellraw @s ["",{"text":"Click ","color":"yellow"},{"text":"[refill kit]","color":"aqua","clickEvent":{"action":"run_command","value":"/function bi:kit"}},{"text":" to run /function bi:kit again","color":"yellow"}]'
)

function Write-TextFile([string]$Path, [string]$Text) {
    [System.IO.File]::WriteAllText($Path, $Text, (New-Object System.Text.UTF8Encoding($false)))
}

function Write-Datapack([string]$WorldDir, [string]$PackMeta, [string]$GameruleStyle) {
    $dp = Join-Path $WorldDir 'datapacks\bundleinventory_playtest'
    Remove-Item $dp -Recurse -Force -ErrorAction SilentlyContinue
    foreach ($d in @('data\bi\function', 'data\bi\tags\function', 'data\minecraft\tags\function')) {
        New-Item -ItemType Directory -Force (Join-Path $dp $d) | Out-Null
    }
    Write-TextFile (Join-Path $dp 'pack.mcmeta') $PackMeta
    Write-TextFile (Join-Path $dp 'data\bi\function\kit.mcfunction') (($kitLines -join "`n") + "`n")
    Write-TextFile (Join-Path $dp 'data\bi\function\tick.mcfunction') "execute as @a unless entity @s[tag=bundleinventory_playtest_kit] run function bi:kit`n"
    Write-TextFile (Join-Path $dp 'data\bi\tags\function\tick.json') '{"values":["bi:tick"]}'
    # World rules run on every load; this avoids editing era-specific level.dat
    # fields (game_rules moved out of level.dat in 1.21.9+). 1.21.11 renamed
    # every rule id to snake_case (advance_time, keep_inventory, ...), so the
    # command names differ by era.
    $load = if ($GameruleStyle -eq 'named') {
        @(
            'gamerule advance_time false',
            'gamerule advance_weather false',
            'gamerule spawn_mobs false',
            'gamerule mob_griefing false',
            'gamerule keep_inventory true',
            'gamerule show_advancement_messages false',
            'gamerule random_tick_speed 0',
            'gamerule fire_spread_radius_around_player 0',
            'time set noon',
            'weather clear'
        ) -join "`n"
    } else {
        @(
            'gamerule doDaylightCycle false',
            'gamerule doWeatherCycle false',
            'gamerule doMobSpawning false',
            'gamerule doFireTick false',
            'gamerule mobGriefing false',
            'gamerule keepInventory true',
            'gamerule announceAdvancements false',
            'gamerule randomTickSpeed 0',
            'time set noon',
            'weather clear'
        ) -join "`n"
    }
    Write-TextFile (Join-Path $dp 'data\bi\function\load.mcfunction') ($load + "`n")
    Write-TextFile (Join-Path $dp 'data\minecraft\tags\function\load.json') '{"values":["bi:load"]}'
}

# "Allow Cheats" is still a one-byte field in level.dat on every era, so patch
# it in place instead of rebuilding (or datafixing) the whole save.
function Enable-Cheats([string]$LevelDat) {
    $compressed = [System.IO.File]::ReadAllBytes($LevelDat)
    $inMs = New-Object System.IO.MemoryStream(, $compressed)
    $gz = New-Object System.IO.Compression.GZipStream($inMs, [System.IO.Compression.CompressionMode]::Decompress)
    $outMs = New-Object System.IO.MemoryStream
    $gz.CopyTo($outMs)
    $gz.Dispose(); $inMs.Dispose()
    $nbt = $outMs.ToArray(); $outMs.Dispose()

    $text = [System.Text.Encoding]::ASCII.GetString($nbt)
    $idx = $text.IndexOf('allowCommands')
    if ($idx -lt 0) { Write-Warning "allowCommands not found in $LevelDat"; return }
    $valueIndex = $idx + 'allowCommands'.Length
    if ($nbt[$valueIndex] -ne 1) {
        $nbt[$valueIndex] = 1
        $outMs = New-Object System.IO.MemoryStream
        $gz = New-Object System.IO.Compression.GZipStream($outMs, [System.IO.Compression.CompressionMode]::Compress)
        $gz.Write($nbt, 0, $nbt.Length)
        $gz.Dispose()
        [System.IO.File]::WriteAllBytes($LevelDat, $outMs.ToArray())
        $outMs.Dispose()
    }
}

function Write-Options([string]$InstanceDir) {
    $path = Join-Path $InstanceDir '.minecraft\options.txt'
    $options = [ordered]@{}
    if (Test-Path $path) {
        foreach ($l in Get-Content $path) {
            $i = $l.IndexOf(':')
            if ($i -gt 0) { $options[$l.Substring(0, $i)] = $l.Substring($i + 1) }
        }
    }
    # Keep rendering while unfocused so the window can be inspected.
    $options['pauseOnLostFocus'] = 'false'
    if (-not $options.Contains('renderDistance')) { $options['renderDistance'] = '8' }
    # Playtest defaults: readable GUI, Quake Pro FOV (fov is normalized, so 1.0
    # is the maximum), music off.
    $options['guiScale'] = '2'
    $options['fov'] = '1.0'
    $options['soundCategory_music'] = '0.0'
    $options.Remove('music')
    Write-TextFile $path (($options.Keys | ForEach-Object { "$($_):$($options[$_])" }) -join "`n")
}

function Set-LaunchWorld([string]$InstanceDir) {
    $cfg = Join-Path $InstanceDir 'instance.cfg'
    # Settings must live in [General]; appending at the end put them under
    # [UI] (which Prism adds after the first launch) and Prism ignored them.
    $filtered = New-Object System.Collections.Generic.List[string]
    foreach ($line in (Get-Content $cfg)) {
        if ($line -match '^(JoinWorldOnLaunch|JoinServerOnLaunch|JoinServerOnLaunchAddress|WrapperCommand|OverrideCommands)=') { continue }
        $filtered.Add($line)
    }
    $idx = -1
    for ($i = 0; $i -lt $filtered.Count; $i++) {
        if ($filtered[$i] -match '^\[General\]$') { $idx = $i; break }
    }
    if ($idx -lt 0) {
        $filtered.Insert(0, '[General]')
        $idx = 0
    }
    $insert = @(
        'JoinServerOnLaunch=true',
        "JoinWorldOnLaunch=$WorldName"
    )
    $filtered.InsertRange($idx + 1, [string[]]$insert)
    Write-TextFile $cfg (($filtered -join "`n") + "`n")
}

# ------------------------------------------------------------- helpers -----
function Test-McAtLeast([string]$mc, [int]$major, [int]$minor, [int]$patch) {
    $p = @($mc.Split('.') | ForEach-Object { [int]$_ })
    while ($p.Count -lt 3) { $p += 0 }
    if ($p[0] -ne $major) { return $p[0] -gt $major }
    if ($p[1] -ne $minor) { return $p[1] -gt $minor }
    return $p[2] -ge $patch
}

function Get-VersionInfo([string]$mc) {
    $jar = Join-Path $PrismData "libraries\com\mojang\minecraft\$mc\minecraft-$mc-client.jar"
    if (-not (Test-Path $jar)) { throw "missing client jar for $mc" }
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $zip = [System.IO.Compression.ZipFile]::OpenRead($jar)
    $e = $zip.Entries | Where-Object { $_.FullName -eq 'version.json' }
    $r = New-Object System.IO.StreamReader($e.Open())
    $version = $r.ReadToEnd() | ConvertFrom-Json
    $r.Dispose(); $zip.Dispose()
    $pv = $version.pack_version
    $legacy = $pv.PSObject.Properties.Name -contains 'data'
    $packMeta = if ($legacy) {
        '{"pack":{"pack_format":' + [int]$pv.data + ',"supported_formats":{"min_inclusive":1,"max_inclusive":9999},"description":"Bundle Inventory playtest kit"}}'
    } else {
        # 1.21.9+ versioned data packs: a min_format below 82 is interpreted as
        # a legacy format and rejected unless supported_formats is present.
        '{"pack":{"min_format":' + [int]$pv.data_major + ',"max_format":9999,"description":"Bundle Inventory playtest kit"}}'
    }
    [pscustomobject]@{
        Mc = $mc
        JavaComponent = $version.java_component
        PackMeta = $packMeta
        # 1.21.11 introduced the namespaced/snake_case gamerule registry.
        GameruleStyle = if ((Test-McAtLeast $mc 1 21 11)) { 'named' } else { 'legacy' }
    }
}

function Get-Java([string]$Component) {
    $candidates = @(
        (Join-Path $PrismData "java\$Component\bin\java.exe"),
        'C:\Program Files\Eclipse Adoptium\jdk-21.0.9.10-hotspot\bin\java.exe',
        'C:\Program Files\Eclipse Adoptium\jdk-25.0.1.8-hotspot\bin\java.exe'
    )
    foreach ($c in $candidates) { if (Test-Path $c) { return $c } }
    throw "no java runtime for $Component"
}

function Get-ServerJar([string]$mc) {
    $dest = Join-Path $work "servers\server-$mc.jar"
    if (Test-Path $dest) { return $dest }
    $manifest = Invoke-RestMethod 'https://piston-meta.mojang.com/mc/game/version_manifest_v2.json'
    $entry = $manifest.versions | Where-Object { $_.id -eq $mc } | Select-Object -First 1
    if (-not $entry) { throw "no server for $mc" }
    $meta = Invoke-RestMethod $entry.url
    Write-Host ("downloading $mc server jar (" + [math]::Round($meta.downloads.server.size / 1MB, 1) + " MB)")
    Invoke-WebRequest $meta.downloads.server.url -OutFile $dest -UseBasicParsing
    return $dest
}

function Invoke-Server([string]$RunDir, [string]$Java, [int]$TimeoutSeconds = 300) {
    $log = Join-Path $RunDir 'console.log'
    Remove-Item $log -Force -ErrorAction SilentlyContinue
    $p = Start-Process -FilePath $Java -ArgumentList @('-Xmx2G', '-jar', 'server.jar', 'nogui') `
        -WorkingDirectory $RunDir -RedirectStandardOutput $log `
        -RedirectStandardError (Join-Path $RunDir 'console.err.log') -PassThru -WindowStyle Hidden
    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
    $done = $false
    while ((Get-Date) -lt $deadline) {
        Start-Sleep -Milliseconds 1500
        if ($p.HasExited) { break }
        if (Test-Path $log) {
            $t = Get-Content $log -Raw -ErrorAction SilentlyContinue
            if ($t -match 'Done \(') { $done = $true; Start-Sleep -Seconds 2; break }
        }
    }
    if (-not $p.HasExited) { Stop-Process -Id $p.Id -Force }
    Start-Sleep -Seconds 1
    return [pscustomobject]@{ Log = $log; Done = $done }
}

# --------------------------------------------------------------- collect ---
Add-Type -AssemblyName System.IO.Compression.FileSystem
$instances = Get-ChildItem $instanceRoot -Directory | Where-Object { $_.Name -like 'BI *' }
if ($Only.Count -gt 0) { $instances = $instances | Where-Object { $Only -contains $_.Name } }
$specs = @()
foreach ($instance in $instances) {
    $packFile = Join-Path $instance.FullName 'mmc-pack.json'
    if (-not (Test-Path $packFile)) { continue }
    $pack = Get-Content $packFile -Raw | ConvertFrom-Json
    $mc = ($pack.components | Where-Object { $_.uid -eq 'net.minecraft' } | Select-Object -First 1).version
    if (-not $mc) { continue }
    $specs += [pscustomobject]@{ Name = $instance.Name; Dir = $instance.FullName; Mc = $mc }
}
if ($specs.Count -eq 0) { throw 'no BI instances found' }

$infos = @{}
foreach ($mc in ($specs | Select-Object -ExpandProperty Mc | Sort-Object -Unique)) {
    $infos[$mc] = Get-VersionInfo $mc
}

# ------------------------------------------------------------- generate ----
$failures = @()
foreach ($mc in ($specs | Select-Object -ExpandProperty Mc | Sort-Object -Unique)) {
    $info = $infos[$mc]
    $java = Get-Java $info.JavaComponent
    $serverJar = Get-ServerJar $mc
    $run = Join-Path $work "gen-$mc"
    Remove-Item $run -Recurse -Force -ErrorAction SilentlyContinue
    New-Item -ItemType Directory -Force $run | Out-Null
    Copy-Item $serverJar (Join-Path $run 'server.jar') -Force
    Write-TextFile (Join-Path $run 'eula.txt') "eula=true`n"
    Write-TextFile (Join-Path $run 'server.properties') (@(
        "level-name=$WorldName",
        'level-type=flat',
        'level-seed=bundleinventory',
        'gamemode=creative',
        'difficulty=peaceful',
        'allow-flight=true',
        'spawn-protection=0',
        'spawn-monsters=false',
        'spawn-animals=false',
        'spawn-npcs=false',
        'generate-structures=false',
        'online-mode=false',
        'max-tick-time=-1',
        'view-distance=4',
        'simulation-distance=4',
        'sync-chunk-writes=false',
        'server-port=25599'
    ) -join "`n" + "`n")

    Write-Output "=== ${mc}: generating flat world ($([System.IO.Path]::GetFileName($java)))"
    $first = Invoke-Server $run $java
    if (-not $first.Done) { $failures += "$mc (world generation failed)"; Write-Warning "${mc}: server did not finish"; continue }

    $world = Join-Path $run $WorldName
    if (-not (Test-Path (Join-Path $world 'level.dat'))) { $failures += "$mc (no level.dat)"; continue }
    Write-Datapack $world $info.PackMeta $info.GameruleStyle
    Enable-Cheats (Join-Path $world 'level.dat')

    # Second start: the server parses every datapack function and reports
    # invalid items/components/commands, which validates the whole kit.
    Write-Output "=== ${mc}: validating datapack"
    $second = Invoke-Server $run $java
    $logText = Get-Content $second.Log -Raw -ErrorAction SilentlyContinue
    $problems = @()
    foreach ($pattern in @('Failed to load function', "Couldn't parse", 'Whilst parsing', 'Unknown item', 'Incompatible pack', 'Failed to load datapack', 'Failed to load tag')) {
        if ($logText -match [regex]::Escape($pattern)) { $problems += $pattern }
    }
    if (-not $second.Done) { $problems += 'server did not finish' }
    if ($problems.Count -gt 0) {
        $failures += "$mc ($($problems -join ', '))"
        Write-Warning "${mc}: $($problems -join ', ')"
        Select-String -Path $second.Log -Pattern 'Failed to load|parse|Incompatible' -Context 0,2 | Select-Object -First 6 | ForEach-Object { Write-Output ('  ' + $_.Line) }
    } else {
        Write-Output "    world + kit OK ($([math]::Round((Get-ChildItem $world -Recurse -File | Measure-Object Length -Sum).Sum / 1MB, 1)) MB)"
    }

    foreach ($spec in ($specs | Where-Object { $_.Mc -eq $mc })) {
        $dest = Join-Path $spec.Dir ".minecraft\saves\$WorldName"
        Remove-Item $dest -Recurse -Force -ErrorAction SilentlyContinue
        Copy-Item $world $dest -Recurse -Force
        Write-Options $spec.Dir
        Set-LaunchWorld $spec.Dir
        Write-Output ("    -> " + $spec.Name)
    }
}

Write-Output ''
if ($failures.Count -gt 0) {
    Write-Warning ("failed: " + ($failures -join '; '))
    exit 1
}
$count = ($specs | Measure-Object).Count
Write-Output "wrote `"$WorldName`" into $count instances; Prism now joins it directly."
Write-Output 'Kit (once per world; click the chat prompt or run /function bi:kit to refill):'
Write-Output '  hotbar 1-9  empty / partial 44 / full 64 / nearly full 63 / nested / scroll 60 / unstackables / one item / dirt'
Write-Output '  inventory   cobblestone, pearls, torches, bread, spare bundle, shulker box (bundles refuse it)'
